import React from "react";
import { Github, ExternalLink } from "lucide-react";

const Project = () => {
  const projects = [
    {
      title: "LED Lighting Store (Light Palace)",
      image: "/images/led-store.jpg",
      description:
        "An online LED lighting store built using React and PHP backend with MySQL. Includes product listing, cart, and admin panel for inventory management.",
      tech: ["React", "PHP", "MySQL", "CSS"],
      github: "https://github.com/yourusername/light-palace",
      live: "https://lightpalace-demo.netlify.app",
    },
    {
      title: "Electrician Service App",
      image: "/images/electrician-app.jpg",
      description:
        "Android application developed with Java and Volley for networking. Allows users to book electrical services, chat, and track service history.",
      tech: ["Java", "XML", "Volley", "Firebase"],
      github: "https://github.com/yourusername/electrician-app",
      live: "#",
    },
    {
      title: "Cloth E-commerce App",
      image: "/images/cloth-app.jpg",
      description:
        "A Flutter-based e-commerce application for clothing with PHP & MySQL backend. Includes admin dashboard, authentication, and product management.",
      tech: ["Flutter", "PHP", "MySQL"],
      github: "https://github.com/yourusername/cloth-ecommerce",
      live: "#",
    },
  ];

  return (
    <section className="project-section" id="projects">
      <div className="container">
        <p className="project-subtitle">PROJECTS</p>
        <h2 className="project-title">My Recent Work</h2>

        <div className="project-grid">
          {projects.map((project, index) => (
            <div className="project-card" key={index}>
              <div className="project-img">
                <img src={project.image} alt={project.title} />
              </div>
              <div className="project-content">
                <h3 className="project-name">{project.title}</h3>
                <p className="project-description">{project.description}</p>
                <div className="project-tech">
                  {project.tech.map((t, i) => (
                    <span key={i}>{t}</span>
                  ))}
                </div>
                <div className="project-links">
                  <a href={project.github} target="_blank" rel="noreferrer">
                    <Github size={20} /> Code
                  </a>
                  <a href={project.live} target="_blank" rel="noreferrer">
                    <ExternalLink size={20} /> Live
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Project;
